(function(){
const RUBRIC=[['assessment','Assessment and monitoring',20,'Latest vitals, focused assessment narrative, and abnormal-cue recognition are present.'],['meds','Medication and order safety',20,'Medication actions, allergy checks, hold parameters, and priority order completion are documented.'],['reasoning','Clinical reasoning and prioritization',20,'Reasoning prompts, nursing priorities, care plan, and debriefing show defensible clinical judgment.'],['communication','Communication and handoff',20,'SBAR is complete and supported by provider notification or handoff-ready documentation.'],['documentation','Education and documentation quality',20,'Patient education, signed notes, I/O, timestamps, and evaluations are complete enough for continuity.']];
let activePanel='check';
function E(v){return typeof esc==='function'?esc(v):String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function W(v){return String(v||'').trim().split(/\s+/).filter(Boolean).length}
function H(v){return String(v||'').trim().length>0}
function L(a){return Array.isArray(a)&&a.length?a[a.length-1]:{}}
function rubric(p){
 p=p||{};const vit=p.vitals||[],med=p.meds||[],ord=p.orders||[],notes=p.notes||[],care=p.carePlan||[],edu=p.education||[],io=p.io||[],s=p.sbar||{},rr=p.reasoningResponses||{},db=p.debriefing||{},as=p.assessment||{};
 const al=String(p.allergies||'').toLowerCase(),hasAl=al&&al!=='nkda'&&al!=='nka',medActions=med.filter(m=>['given','hold','not_given'].includes(m.status)).length,ordDone=ord.filter(o=>o.nurseCompleted||String(o.status||'').toLowerCase()==='complete').length;
 const c={
 assessment:{score:(vit.length?6:0)+(vit.length>=2?4:0)+(W(as.narrative)>=15?6:0)+(notes.some(n=>/reassess|worsen|improv|alert|notify/i.test(n.body||''))?4:0),issues:[!vit.length&&'Add at least one complete vital-sign set.',vit.length<2&&'Add a reassessment vital-sign set after intervention or time passes.',W(as.narrative)<15&&'Write a focused assessment narrative with priority cues.',!notes.some(n=>/reassess|worsen|improv|alert|notify/i.test(n.body||''))&&'Document recognition of abnormal cues or patient response.'].filter(Boolean)},
 meds:{score:(med.length?4:0)+(med.length&&medActions===med.length?6:medActions?3:0)+(hasAl?(notes.some(n=>/allerg/i.test(n.body||''))?4:0):4)+(ord.length&&ordDone?4:0)+(med.some(m=>H(m.note)||H(m.warn))?2:0),issues:[!med.length&&'Add or reconcile the medication administration record.',med.length&&medActions<med.length&&'Mark each medication as given, held, not given, or pending with rationale.',hasAl&&!notes.some(n=>/allerg/i.test(n.body||''))&&'Document allergy verification before medication administration.',ord.length&&!ordDone&&'Complete or address at least one priority provider order.',!med.some(m=>H(m.note)||H(m.warn))&&'Add medication safety notes, hold parameters, or response documentation.'].filter(Boolean)},
 reasoning:{score:(Object.values(rr).filter(H).length?8:0)+(care.some(x=>H(x.dx))?5:0)+(care.some(x=>H(x.interventions))?3:0)+(H(db.strengths)?2:0)+(H(db.improvements)?2:0),issues:[!Object.values(rr).filter(H).length&&'Answer the clinical reasoning prompts.',!care.some(x=>H(x.dx))&&'Add a priority nursing diagnosis or problem.',!care.some(x=>H(x.interventions))&&'Link interventions to the priority problem.',!H(db.strengths)&&'Complete the debriefing strength field.',!H(db.improvements)&&'Complete the debriefing improvement field.'].filter(Boolean)},
 communication:{score:(H(s.s)?3:0)+(H(s.b)?3:0)+(H(s.a)?3:0)+(H(s.r)?3:0)+(notes.some(n=>/sbar|provider|notify|handoff|report/i.test(`${n.type||''} ${n.body||''}`))?5:0)+(vit.length&&H(L(vit).note)?3:0),issues:[!H(s.s)&&'Complete SBAR Situation.',!H(s.b)&&'Complete SBAR Background.',!H(s.a)&&'Complete SBAR Assessment.',!H(s.r)&&'Complete SBAR Recommendation.',!notes.some(n=>/sbar|provider|notify|handoff|report/i.test(`${n.type||''} ${n.body||''}`))&&'Sign a note showing provider notification or handoff communication.'].filter(Boolean)},
 documentation:{score:(edu.some(e=>e.status==='Complete')?5:0)+(edu.some(e=>H(e.response))?3:0)+(notes.length?4:0)+(io.length?3:0)+(care.some(x=>H(x.evaluation))?3:0)+(notes.some(n=>H(n.time)&&H(n.by))?2:0),issues:[!edu.some(e=>e.status==='Complete')&&'Complete at least one patient education topic.',!edu.some(e=>H(e.response))&&'Document learner or patient response to education.',!notes.length&&'Add a signed nursing note.',!io.length&&'Chart intake/output when relevant to the scenario.',!care.some(x=>H(x.evaluation))&&'Evaluate the care plan goal or intervention response.'].filter(Boolean)}
 };
 const details=RUBRIC.map(r=>({key:r[0],label:r[1],points:r[2],guide:r[3],score:Math.min(r[2],c[r[0]].score),issues:c[r[0]].issues}));return{total:details.reduce((a,x)=>a+x.score,0),details,issues:details.flatMap(x=>x.issues.map(t=>({category:x.label,text:t})))};
}
function status(n){return n>=85?['Ready for instructor review','ok']:n>=70?['Needs minor cleanup','warn']:['Needs completion before submission','risk']}
function timeline(p){const ev=[];(p.vitals||[]).forEach(v=>ev.push({time:v.time,title:'Vitals charted',body:`HR ${v.hr||'--'}, BP ${v.bps||'--'}/${v.bpd||'--'}, RR ${v.rr||'--'}, SpO2 ${v.spo2||'--'}%. ${v.note||''}`}));(p.labs||[]).forEach(l=>ev.push({time:l.time,title:`Lab ${l.flag||''}: ${l.test||'result'}`,body:`${l.result||'--'} ${l.range?`(ref ${l.range})`:''} ${l.note||''}`}));(p.meds||[]).filter(m=>m.status&&m.status!=='pending').forEach(m=>ev.push({time:m.time||'',title:`Medication ${m.status}`,body:`${m.name||'Medication'} ${m.dose||''} ${m.route||''}. ${m.note||m.warn||''}`}));(p.io||[]).forEach(e=>ev.push({time:e.time,title:`I/O ${e.direction||''}`,body:`${e.type||'entry'} ${e.amount?`${e.amount} mL`:''}. ${e.characteristic||e.note||''}`}));(p.orders||[]).filter(o=>o.nurseCompleted||String(o.status||'').toLowerCase()==='complete').forEach(o=>ev.push({time:'',title:'Order completed',body:`${o.order||''}. ${o.details||''}`}));(p.notes||[]).forEach(n=>ev.push({time:n.time,title:n.type||'Nursing note',body:n.body||''}));if(p.sbar&&(p.sbar.s||p.sbar.a||p.sbar.r))ev.push({time:'',title:'SBAR prepared',body:[p.sbar.s,p.sbar.a,p.sbar.r].filter(Boolean).join(' ')});return ev.sort((a,b)=>String(a.time||'9999').localeCompare(String(b.time||'9999'))).slice(-14)}
function handoff(p){const v=L(p.vitals||[]),pend=(p.meds||[]).filter(m=>!m.status||m.status==='pending').map(m=>m.name).filter(Boolean),orders=(p.orders||[]).filter(o=>!o.nurseCompleted&&String(o.status||'').toLowerCase()!=='complete').map(o=>o.order).filter(Boolean),alerts=rubric(p).issues.slice(0,4).map(i=>`- ${i.text}`);return[`Patient: ${p.lastName||''}, ${p.firstName||''} | MRN ${p.mrn||''}`,`Diagnosis: ${p.diagnosis||'Not documented'} | Acuity: ${p.acuity||'Not documented'}`,`Situation: ${p.sbar?.s||p.chiefComplaint||'Situation not documented.'}`,`Background: ${p.sbar?.b||p.hpi||p.background||'Background not documented.'}`,`Latest vitals: HR ${v.hr||'--'}, BP ${v.bps||'--'}/${v.bpd||'--'}, RR ${v.rr||'--'}, SpO2 ${v.spo2||'--'}%, Pain ${v.pain||'--'}.`,`Assessment: ${p.sbar?.a||p.assessment?.narrative||'Focused assessment not documented.'}`,`Recommendation: ${p.sbar?.r||'Recommendation not documented.'}`,`Pending medications: ${pend.length?pend.join(', '):'None documented.'}`,`Active orders: ${orders.length?orders.slice(0,5).join(', '):'None documented.'}`,`Priority cleanup:\n${alerts.length?alerts.join('\n'):'- No major chart gaps detected.'}`].join('\n\n')}
function comment(res,p){return[`Objective rubric score: ${res.total}/100`,'',res.details.map(x=>`${x.label}: ${x.score}/${x.points} - ${x.guide}`).join('\n'),'','Priority feedback:',res.issues.slice(0,6).map(i=>`- ${i.text}`).join('\n')||'- No major chart gaps detected.','','Handoff snapshot:',handoff(p)].join('\n')}
function checkHtml(p){const r=rubric(p),s=status(r.total),items=r.issues.slice(0,8).map(i=>`<li><span class="lb-dot ${s[1]}"></span><span><strong>${E(i.category)}:</strong> ${E(i.text)}</span></li>`).join(''),rows=r.details.map(x=>`<div class="lb-rubric-row"><strong><span>${E(x.label)}</span><span>${x.score}/${x.points}</span></strong><p>${E(x.guide)}</p></div>`).join('');return`<div class="lb-score-grid"><div class="lb-score"><strong>${r.total}</strong><span>${E(s[0])}</span></div><div><ul class="lb-list">${items||'<li><span class="lb-dot ok"></span><span>No major chart gaps detected.</span></li>'}</ul><div class="lb-rubric" style="margin-top:12px;">${rows}</div></div></div>`}
function timeHtml(p){return`<div class="lb-timeline">${timeline(p).map(e=>`<div class="lb-event"><time>${E(e.time||'No time')}</time><div><strong>${E(e.title)}</strong><span>${E(e.body)}</span></div></div>`).join('')||'<p class="text-block">No timeline events yet.</p>'}</div>`}
function handHtml(p){return`<textarea class="lb-handoff" id="lb-handoff-text">${E(handoff(p))}</textarea><div class="actions"><button class="btn" id="lb-copy-handoff">Copy handoff</button></div>`}
function bundleHtml(p){const r=rubric(p),s=status(r.total),pan={check:checkHtml(p),timeline:timeHtml(p),handoff:handHtml(p)};return`<div class="learning-bundle" id="learning-bundle"><div class="learning-bundle__head"><div><p class="learning-bundle__title">Chart readiness bundle</p><div class="learning-bundle__meta">${r.total}/100 - ${E(s[0])}</div></div><div class="lb-tabs">${Object.keys(pan).map(k=>`<button class="lb-tab ${activePanel===k?'active':''}" data-lb-panel="${k}">${E(k==='check'?'Completeness':k==='timeline'?'Timeline':'Handoff')}</button>`).join('')}</div></div><div class="learning-bundle__body">${Object.entries(pan).map(([k,h])=>`<div class="lb-panel ${activePanel===k?'active':''}">${h}</div>`).join('')}</div></div>`}
function addStudent(){const c=document.getElementById('content');if(!c||document.getElementById('learning-bundle'))return;if(typeof state==='undefined'||['dashboard','statusboard'].includes(state.tab))return;c.insertAdjacentHTML('afterbegin',bundleHtml(currentPatient()))}
function enhanceDashboard(){if(typeof state==='undefined'||state.tab!=='dashboard')return;const selected=typeof dashboardRows!=='undefined'?dashboardRows.find(r=>r.id===dashboardSelectedId):null;if(!selected||document.getElementById('lb-rubric-tools'))return;const side=document.querySelector(`[data-save-review="${selected.id}"]`)?.closest('.actions');if(!side)return;const p=selected.chart?.patient||{},r=rubric(p);side.insertAdjacentHTML('beforebegin',`<div id="lb-rubric-tools" class="lb-rubric" style="margin-top:12px;"><div class="lb-rubric-row"><strong><span>Objective rubric score</span><span>${r.total}/100</span></strong><p>Use this to prefill score and comments from observable chart evidence.</p></div>${r.details.map(x=>`<div class="lb-rubric-row"><strong><span>${E(x.label)}</span><span>${x.score}/${x.points}</span></strong><p>${E(x.guide)}</p></div>`).join('')}<button class="btn navy" id="lb-apply-rubric" type="button">Apply objective rubric</button></div>`)}
function bind(){document.querySelectorAll('[data-lb-panel]').forEach(b=>b.onclick=()=>{activePanel=b.dataset.lbPanel;render()});document.getElementById('lb-copy-handoff')?.addEventListener('click',()=>{const t=document.getElementById('lb-handoff-text')?.value||'';navigator.clipboard?.writeText(t).then(()=>toast('Handoff copied')).catch(()=>prompt('Copy handoff:',t))});document.getElementById('lb-apply-rubric')?.addEventListener('click',()=>{const row=dashboardRows.find(r=>r.id===dashboardSelectedId);if(!row)return;const p=row.chart?.patient||{},r=rubric(p),score=document.getElementById(`review-score-${row.id}`),text=document.getElementById(`review-comment-${row.id}`);if(score)score.value=r.total;if(text)text.value=comment(r,p)})}
function augment(){try{addStudent();enhanceDashboard();bind()}catch(e){console.warn('Learning bundle failed:',e)}}
function install(){if(typeof render==='function'&&!render.__learningBundle){const old=render;render=function(){const out=old.apply(this,arguments);augment();return out};render.__learningBundle=true}if(typeof submitCurrentChart==='function'&&!submitCurrentChart.__learningBundle){const oldSubmit=submitCurrentChart;submitCurrentChart=async function(){const r=rubric(currentPatient());if(r.total<85){const msg=[`Chart readiness score is ${r.total}/100.`,'','Top items to fix:',...r.issues.slice(0,5).map(i=>`- ${i.text}`),'','Submit anyway?'].join('\n');if(!confirm(msg))return}return oldSubmit.apply(this,arguments)};submitCurrentChart.__learningBundle=true}window.HCTLearningBundle={getRubric:rubric,buildTimeline:timeline,handoffSummary:handoff,reviewComment:comment,guide:RUBRIC};augment()}
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',install):install();
})();
